import os
os.environ['TORCH_CUDA_ARCH_LIST'] = '9.0a'
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <limits>

template <typename scalar_t>
__device__ __forceinline__ float ld_as_float(const scalar_t* p) {
    return static_cast<float>(*p);
}

template <typename scalar_t>
__device__ __forceinline__ void st_from_float(scalar_t* p, float v) {
    *p = static_cast<scalar_t>(v);
}

__device__ __forceinline__ float warp_reduce_max(float v) {
    unsigned mask = 0xffffffffu;
    v = fmaxf(v, __shfl_down_sync(mask, v, 16));
    v = fmaxf(v, __shfl_down_sync(mask, v, 8));
    v = fmaxf(v, __shfl_down_sync(mask, v, 4));
    v = fmaxf(v, __shfl_down_sync(mask, v, 2));
    v = fmaxf(v, __shfl_down_sync(mask, v, 1));
    return v;
}

__device__ __forceinline__ float warp_reduce_sum(float v) {
    unsigned mask = 0xffffffffu;
    v += __shfl_down_sync(mask, v, 16);
    v += __shfl_down_sync(mask, v, 8);
    v += __shfl_down_sync(mask, v, 4);
    v += __shfl_down_sync(mask, v, 2);
    v += __shfl_down_sync(mask, v, 1);
    return v;
}

template <typename scalar_t, int WARPS_PER_BLOCK>
__global__ __launch_bounds__(WARPS_PER_BLOCK*32, 8)
void softmax_warp_kernel(scalar_t* __restrict__ y, const scalar_t* __restrict__ x,
                         int64_t N, int64_t D, int64_t xs0, int64_t ys0) {
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp_in_block = tid >> 5;
    int64_t global_warp = (int64_t)blockIdx.x * WARPS_PER_BLOCK + warp_in_block;
    int64_t warp_stride = (int64_t)gridDim.x * WARPS_PER_BLOCK;

    for (int64_t row = global_warp; row < N; row += warp_stride) {
        const scalar_t* row_x = x + row * xs0;
        scalar_t* row_y = y + row * ys0;
        float m = -CUDART_INF_F;
        for (int64_t col = lane; col < D; col += 32) {
            m = fmaxf(m, ld_as_float(row_x + col));
        }
        m = warp_reduce_max(m);
        m = __shfl_sync(0xffffffffu, m, 0);
        float s = 0.0f;
        for (int64_t col = lane; col < D; col += 32) {
            s += __expf(ld_as_float(row_x + col) - m);
        }
        s = warp_reduce_sum(s);
        s = __shfl_sync(0xffffffffu, s, 0);
        float inv = 1.0f / s;
        for (int64_t col = lane; col < D; col += 32) {
            float v = __expf(ld_as_float(row_x + col) - m) * inv;
            st_from_float(row_y + col, v);
        }
    }
}

template <typename scalar_t, int BLOCK_THREADS>
__global__ __launch_bounds__(BLOCK_THREADS, 4)
void softmax_block_kernel(scalar_t* __restrict__ y, const scalar_t* __restrict__ x,
                          int64_t N, int64_t D, int64_t xs0, int64_t ys0) {
    __shared__ float smem[32];
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp = tid >> 5;
    int nwarps = BLOCK_THREADS >> 5;
    for (int64_t row = blockIdx.x; row < N; row += gridDim.x) {
        const scalar_t* row_x = x + row * xs0;
        scalar_t* row_y = y + row * ys0;
        float m = -CUDART_INF_F;
        for (int64_t col = tid; col < D; col += BLOCK_THREADS) {
            m = fmaxf(m, ld_as_float(row_x + col));
        }
        m = warp_reduce_max(m);
        if (lane == 0) smem[warp] = m;
        __syncthreads();
        float bm = (tid < nwarps) ? smem[lane] : -CUDART_INF_F;
        if (warp == 0) bm = warp_reduce_max(bm);
        if (tid == 0) smem[0] = bm;
        __syncthreads();
        m = smem[0];

        float s = 0.0f;
        for (int64_t col = tid; col < D; col += BLOCK_THREADS) {
            s += __expf(ld_as_float(row_x + col) - m);
        }
        s = warp_reduce_sum(s);
        if (lane == 0) smem[warp] = s;
        __syncthreads();
        float bs = (tid < nwarps) ? smem[lane] : 0.0f;
        if (warp == 0) bs = warp_reduce_sum(bs);
        if (tid == 0) smem[0] = bs;
        __syncthreads();
        float inv = 1.0f / smem[0];
        for (int64_t col = tid; col < D; col += BLOCK_THREADS) {
            float v = __expf(ld_as_float(row_x + col) - m) * inv;
            st_from_float(row_y + col, v);
        }
        __syncthreads();
    }
}

torch::Tensor softmax_forward(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "expected 2D tensor");
    TORCH_CHECK(x.is_cuda(), "expected CUDA tensor");
    auto y = torch::empty_like(x);
    int64_t N = x.size(0);
    int64_t D = x.size(1);
    if (N == 0 || D == 0) return y;
    int64_t xs0 = x.stride(0);
    int64_t ys0 = y.stride(0);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    int sm_count = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    if (D <= 1024) {
        constexpr int WPB = 8;
        int64_t total_warps = N < (int64_t)sm_count * 32 ? N : (int64_t)sm_count * 32;
        int blocks = (int)((total_warps + WPB - 1) / WPB);
        if (blocks < 1) blocks = 1;
        AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, x.scalar_type(), "softmax_warp", [&] {
            softmax_warp_kernel<scalar_t, WPB><<<blocks, WPB*32, 0, stream>>>(y.data_ptr<scalar_t>(), x.data_ptr<scalar_t>(), N, D, xs0, ys0);
        });
    } else {
        constexpr int BT = 256;
        int blocks = (int)((N < (int64_t)sm_count * 8) ? N : (int64_t)sm_count * 8);
        if (blocks < 1) blocks = 1;
        AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, x.scalar_type(), "softmax_block", [&] {
            softmax_block_kernel<scalar_t, BT><<<blocks, BT, 0, stream>>>(y.data_ptr<scalar_t>(), x.data_ptr<scalar_t>(), N, D, xs0, ys0);
        });
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("softmax_forward", &softmax_forward, "row softmax forward");
}
'''

_ext = load_inline(name='h100_row_softmax_ext_v1', cpp_sources='', cuda_sources=_src, functions=['softmax_forward'], extra_cuda_cflags=['-O3', '--use_fast_math'], extra_cflags=['-O3'], verbose=False)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _ext.softmax_forward(x)
